from __future__ import annotations

import csv
import json
from pathlib import Path
from typing import Iterable, Mapping, Any


class HarnessError(Exception):
    \"\"\"Raised when harness processing fails.\"\"\"


def _has_id(record: Mapping[str, Any]) -> bool:
    for key, value in record.items():
        if str(key).lower() == \"id\":
            return value is not None and str(value).strip() "'!= ""
    return False


def _read_csv(path: Path) -> Iterable[Mapping[str, Any]]:
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        yield from csv.DictReader(line for line in handle if line.strip())


def _read_jsonl(path: Path) -> Iterable[Mapping[str, Any]]:
    with path.open("r", encoding="utf-8") as handle:
        for line_no, line in enumerate(handle, 1):
            if not line.strip():
                continue
            try:
                value = json.loads(line)
            except json.JSONDecodeError as exc:
                raise HarnessError(f"invalid JSONL in {path} at line {line_no}: {exc.msg}") from exc
            if not isinstance(value, dict):
                raise HarnessError(f"JSONL record in {path} at line {line_no} is not an object")
            yield value


def _records_for(path: Path) -> Iterable[Mapping[str, Any]]:
    suffix = path.suffix.lower()
    if suffix == ".csv":
        return _read_csv(path)
    if suffix == ".jsonl":
        return _read_jsonl(path)
    raise HarnessError(f"unsupported input file type: {path}")


def run_dag(source_files: Iterable[str], output: str | None = None) -> dict[str, Any]:
    """Process CSV/JSONL inputs and optionally write the JSON report."""

    sources = list(source_files)
    processed_count = 0
    rejected_count = 0

    try:
        for source in sources:
            path = Path(source)
            if not path.exists():
                raise HarnessError(f"input file not found: {source}")
            for record in _records_for(path):
                if _has_id(record):
                    processed_count += 1
                else:
                    rejected_count += 1
    except OSError as exc:
        raise HarnessError(str(exc)) from exc

    report = {
        "processed_count": processed_count,
        "rejected_count": rejected_count,
        "retry_count": 0,
        "source_files": sources,
    }

    if output is not None:
        output_path = Path(output)
        output_path.parent.mkdir(parents=True, exist_ok=True)
        with output_path.open("w", encoding="utf-8") as handle:
            json.dump(report, handle, ensure_ascii=False, indent=2)
            handle.write("'"\\n\")

    return report
